package com.alpharip.staffmod.cases.caseredactiontool; import java.util.*; public final class RedactionDocument { private final String id,title,source; private final List<RedactionEntry> entries; public RedactionDocument(String id,String title,String source,List<RedactionEntry> entries){if(id==null||id.trim().isEmpty()||title==null||title.trim().isEmpty()||source==null)throw new IllegalArgumentException("ID, title and source required");this.id=id.trim();this.title=title.trim();this.source=source;this.entries=Collections.unmodifiableList(new ArrayList<RedactionEntry>(entries==null?Collections.<RedactionEntry>emptyList():entries));for(RedactionEntry e:this.entries)if(e.getEnd()>source.length())throw new IllegalArgumentException("Range exceeds source");} public String getId(){return id;} public String getTitle(){return title;} public String getSource(){return source;} public List<RedactionEntry> getEntries(){return entries;} public String renderRedacted(){char[] a=source.toCharArray();boolean[] m=new boolean[a.length];for(RedactionEntry e:entries)if(e.isEnabled())for(int i=e.getStart();i<e.getEnd();i++)m[i]=true;for(int i=0;i<a.length;i++)if(m[i]&&a[i]!='\n'&&a[i]!='\r')a[i]='█';return new String(a);} public RedactionDocument add(RedactionEntry e){List<RedactionEntry> n=new ArrayList<RedactionEntry>(entries);n.add(e);return new RedactionDocument(id,title,source,n);} }